export const SCRIPT_FIXED_TUPLES_FACTS = "defold-script-fixed-tuples-recipe-facts.json";

const allCodecs = Object.freeze([
  "Nil",
  "Boolean",
  "Integer",
  "Number",
  "String",
  "Hash",
  "Url",
  "GuiNode",
  "LuaUserdata",
  "Vector3",
  "Vector4",
  "Quaternion",
]);
const cpp = (value) => JSON.stringify(value);

function validate(facts) {
  if (
    facts?.schemaVersion !== 1 ||
    facts.kind !== "deherm.recipe.script-fixed-tuples-output" ||
    !Array.isArray(facts.bindings) ||
    facts.bindings.some(
      (row, index) =>
        row.index !== index ||
        typeof row.id !== "string" ||
        !/^0x[0-9a-f]{8}$/.test(row.stableId) ||
        !Array.isArray(row.modulePath) ||
        typeof row.member !== "string" ||
        !["Global", "ScriptInstance", "GuiScriptInstance"].includes(row.context) ||
        !Number.isInteger(row.requiredArgumentCount) ||
        !Number.isInteger(row.maximumArgumentCount) ||
        !Array.isArray(row.arguments) ||
        !Array.isArray(row.results),
    )
  ) {
    throw new Error("Unsupported script fixed-tuples recipe facts");
  }
  return facts.bindings;
}

export function createScriptFixedTuplesRecipeFacts(report) {
  return {
    schemaVersion: 1,
    kind: "deherm.recipe.script-fixed-tuples-output",
    bindings: report.bindings.map((row, index) => ({
      index,
      id: row.id,
      stableId: row.stableId,
      modulePath: row.modulePath,
      member: row.member,
      context: row.context,
      requiredArgumentCount: row.requiredArgumentCount,
      maximumArgumentCount: row.maximumArgumentCount,
      arguments: row.arguments.map(({ implementedCodecs }) => implementedCodecs),
      results: row.results.map(({ codecs }) => codecs),
    })),
  };
}

export function renderScriptFixedTuplesOutputs(facts) {
  const rows = validate(facts);
  const flatArgs = rows.flatMap((row) => row.arguments);
  const flatResults = rows.flatMap((row) => row.results);
  const codecBits = new Map(allCodecs.map((name, index) => [name, 1 << index]));
  const argMasks = flatArgs.map((codecs) => codecs.reduce((bits, codec) => bits | codecBits.get(codec), 0));
  const resultMasks = flatResults.map((codecs) => codecs.reduce((bits, codec) => bits | codecBits.get(codec), 0));
  let argOffset = 0;
  let resultOffset = 0;
  const descriptors = rows.map((row) => {
    const value = { ...row, argOffset, resultOffset };
    argOffset += row.arguments.length;
    resultOffset += row.results.length;
    return value;
  });
  if (rows.length > 0xffff || argOffset > 0xffff || resultOffset > 0xffff) {
    throw new Error("Fixed-tuple descriptor table exceeds uint16_t capacity");
  }
  const header = `// Generated by scripts/generate-script-fixed-tuples.mjs. Do not edit.\n#pragma once\n\n#include <cstddef>\n#include <cstdint>\n#include <defold_hermes/script_bridge_capi.hpp>\n\nnamespace defold_hermes::fixed_tuple {\nenum class DispatchStatus : uint8_t { kMissing, kSuccess, kError };\nenum class Context : uint8_t { kGlobal, kScriptInstance, kGuiScriptInstance };\nenum CodecMask : uint16_t {\n${allCodecs.map((name, index) => `  k${name} = 1u << ${index},`).join("\n")}\n};\nstruct Operation { uint16_t index; uint32_t stableId; const char* canonicalId; const char* modulePath; const char* member; Context context; uint16_t argumentOffset; uint16_t resultOffset; uint8_t requiredArgumentCount; uint8_t maximumArgumentCount; uint8_t resultCount; };\nstruct LuaApi { void* context = nullptr; DispatchStatus (*invoke)(void*, const Operation&, const uint16_t*, const uint16_t*, ScriptCallFrame*, char*, size_t) noexcept = nullptr; };\ninline constexpr size_t kBindingCount = ${rows.length};\ninline constexpr size_t kMaximumResultCount = ${Math.max(0, ...rows.map((row) => row.results.length))};\nconst Operation* find(uint32_t stableId) noexcept;\nconst uint16_t* argumentCodecs() noexcept;\nconst uint16_t* resultCodecs() noexcept;\nDispatchStatus dispatch(ScriptCallFrame*, char*, size_t, const LuaApi*) noexcept;\n}\n`;
  const entries = descriptors.length
    ? descriptors
        .map(
          (row) =>
            `  {${row.index}, ${row.stableId}u, ${cpp(row.id)}, ${cpp(row.modulePath.join("."))}, ${cpp(row.member)}, Context::k${row.context}, ${row.argOffset}, ${row.resultOffset}, ${row.requiredArgumentCount}, ${row.maximumArgumentCount}, ${row.results.length}},`,
        )
        .join("\n")
    : "  {},  // sentinel storage; kBindingCount remains zero";
  const source = `// Generated by scripts/generate-script-fixed-tuples.mjs. Do not edit.\n#include <defold_hermes/generated_script_fixed_tuples.hpp>\n#include <cmath>\n#include <cstdio>\n\nnamespace defold_hermes::fixed_tuple { namespace {\nconstexpr Operation kOperations[] = {\n${entries}\n};\nconstexpr uint16_t kArgumentCodecs[] = { ${argMasks.join(", ")} };\nconstexpr uint16_t kResultCodecs[] = { ${resultMasks.join(", ")} };\nbool fail(char* error, size_t capacity, const char* message) noexcept { if (error && capacity) std::snprintf(error, capacity, "%s", message); return false; }\nuint16_t valueMask(const ScriptValue& value) noexcept {\n  switch (value.tag) {\n    case ScriptValueTag::kNull: case ScriptValueTag::kUndefined: return kNil;\n    case ScriptValueTag::kBoolean: return kBoolean;\n    case ScriptValueTag::kNumber: return kInteger | kNumber;\n    case ScriptValueTag::kString: return kString;\n    case ScriptValueTag::kHandle: if (value.handleKind == ScriptHandleKind::kHash) return kHash; if (value.handleKind == ScriptHandleKind::kUrl) return kUrl; if (value.handleKind == ScriptHandleKind::kGuiNode) return kGuiNode; if (value.handleKind == ScriptHandleKind::kLuaUserdata) return kLuaUserdata; return 0;\n    case ScriptValueTag::kDefoldValue: if (value.defoldKind == ScriptDefoldValueKind::kVector3) return kVector3; if (value.defoldKind == ScriptDefoldValueKind::kVector4) return kVector4; if (value.defoldKind == ScriptDefoldValueKind::kQuaternion) return kQuaternion; return 0;\n    default: return 0;\n  }\n}\n}\nconst Operation* find(uint32_t stableId) noexcept { size_t first=0,count=kBindingCount; while(count){size_t step=count/2,index=first+step;if(kOperations[index].stableId<stableId){first=index+1;count-=step+1;}else count=step;} return first<kBindingCount&&kOperations[first].stableId==stableId?&kOperations[first]:nullptr; }\nconst uint16_t* argumentCodecs() noexcept { return kArgumentCodecs; }\nconst uint16_t* resultCodecs() noexcept { return kResultCodecs; }\nDispatchStatus dispatch(ScriptCallFrame* frame, char* error, size_t capacity, const LuaApi* api) noexcept {\n  if (!frame) { fail(error,capacity,"Fixed tuple call frame is null"); return DispatchStatus::kError; }\n  const Operation* operation=find(frame->stableId); if(!operation) return DispatchStatus::kMissing; frame->resultCount=0;\n  if(frame->argumentCount<operation->requiredArgumentCount||frame->argumentCount>operation->maximumArgumentCount||(frame->argumentCount&&!frame->arguments)){fail(error,capacity,"Fixed tuple argument count does not match descriptor");return DispatchStatus::kError;}\n  for(uint32_t index=0;index<frame->argumentCount;++index){const ScriptValue& value=frame->arguments[index];const uint16_t mask=valueMask(value);if(!(mask&kArgumentCodecs[operation->argumentOffset+index])){fail(error,capacity,"Fixed tuple argument tag does not match positional codec");return DispatchStatus::kError;}if(value.tag==ScriptValueTag::kNumber&&(kArgumentCodecs[operation->argumentOffset+index]&kInteger)&&!(kArgumentCodecs[operation->argumentOffset+index]&kNumber)&&(!std::isfinite(value.number)||std::trunc(value.number)!=value.number)){fail(error,capacity,"Fixed tuple integer argument is not exact");return DispatchStatus::kError;}}\n  if(!frame->results||frame->resultCapacity<operation->resultCount){fail(error,capacity,"Fixed tuple result storage is exhausted");return DispatchStatus::kError;}\n  if(!api||!api->invoke){fail(error,capacity,"Fixed tuple Lua backend is unavailable");return DispatchStatus::kError;}\n  return api->invoke(api->context,*operation,kArgumentCodecs,kResultCodecs,frame,error,capacity);\n}\n}\n`;
  const target = `// Generated by scripts/generate-script-fixed-tuples.mjs. Do not edit.\n// The fixed-tuple lane is a native codec optimization. Every one of these\n// routes still reaches the browser host through the generated universal\n// direct-memory provider, so this gate carries no route and exists only so the\n// SDK keeps one declared target-support seam per family.\nconst fixedTupleIds: ReadonlySet<string> = new Set<string>([\n${rows.map(({ id }) => `  ${cpp(id)},`).join("\n")}\n]);\nexport function assertFixedTupleTargetSupport(target: string | undefined, stableId: number, canonicalId?: string): void {\n  if (target !== "html5-browser-host") return;\n  void fixedTupleIds;\n  void stableId;\n  void canonicalId;\n}\n`;
  return { header, source, target };
}
